type c = A | B of int | C of int * int

let describe x =
  let r = Obj.repr x in
  if Obj.is_int r then Printf.sprintf "immediate %d" (Obj.obj r : int)
  else
    let tag = Obj.tag r in
    if tag = Obj.double_tag then "boxed float"
    else if tag = Obj.string_tag then "string"
    else if tag = Obj.double_array_tag then Printf.sprintf "float array of %d" (Obj.size r)
    else if tag = Obj.closure_tag then "closure"
    else Printf.sprintf "block tag=%d size=%d" tag (Obj.size r)

let () =
  List.iter print_endline
    [ describe 42; describe true; describe (); describe None; describe [];
      describe (Some 3); describe (1, 2, 3); describe [ 1; 2 ]; describe (ref 0);
      describe 1.5; describe "hi"; describe [| 1.; 2. |]; describe (fun x -> x);
      describe A; describe (B 1); describe (C (1, 2)) ];
  Printf.printf "%d %d\n" (Obj.reachable_words (Obj.repr [ 1; 2; 3 ])) (Obj.reachable_words (Obj.repr (1, 2, 3)))

